def greet(name: str, times: int = 1) -> str:
    return " ".join([f"Hi {name}!"] * times)

print(greet("Asha"))
print(greet("Ravi", 2))

type Vector = list[float]

def total(values: Vector) -> float:
    return sum(values)

print(total([1.5, 2.5]))
print(total([]))

def find(users: list[dict], name: str) -> dict | None:
    for user in users:
        if user['name'] == name:
            return user
    return None

users = [{'name': 'Asha'}, {'name': 'Ravi'}]
print(find(users, 'Ravi'))
print(find(users, 'Mili'))

