def shout(text):
    return text.upper() + "!"

def whisper(text):
    return text.lower() + "..."

def announce(style, text):
    print(style(text))

announce(shout, "hello")
announce(whisper, "HELLO")

def logged(func):
    def wrapper(*args, **kwargs):
        print("calling", func.__name__)
        return func(*args, **kwargs)
    return wrapper

@logged
def add(a, b):
    return a + b

print(add(2, 3))

from functools import wraps

def logged(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@logged
def area(width, height):
    return width * height

print(area.__name__)
print(area(3, 4))

exercises.solution:
def doubled(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs) * 2
    return wrapper

@doubled
def five():
    return 5

print(five())
